//! Outputs must match the original Python implementation exactly for the
//! same maze id. The fixtures were generated by running the Python version
//! (`maze/maze.py`) with the arguments named in each test.

use maze::maze::{create_maze, find_solution, Grid};
use maze::random::PyRandom;
use maze::renderers::pdf::{pdf_content, PdfOptions};
use maze::renderers::svg::svg_render;
use maze::renderers::text::text_render;
use maze::renderers::PageSize;

fn grid(id: &str, width: usize, height: usize, density: i64, add_a_loop: bool) -> Grid {
    create_maze(width, height, density, add_a_loop, &mut PyRandom::from_str_seed(id))
}

fn fixture(name: &str) -> String {
    std::fs::read_to_string(format!("{}/tests/fixtures/{name}", env!("CARGO_MANIFEST_DIR"))).unwrap()
}

#[test]
fn text_matches_python() {
    // maze text -W 6 -H 4 -i abc
    assert_eq!(text_render(&grid("abc", 6, 4, 50, false)), fixture("text-6x4-abc.txt"));
    // maze text -W 12 -H 10 -i hello -L
    assert_eq!(text_render(&grid("hello", 12, 10, 50, true)), fixture("text-12x10-hello-loop.txt"));
}

#[test]
fn svg_matches_python() {
    // maze svg ... -W 10 -H 12 -i abc -s ...
    let g = grid("abc", 10, 12, 50, false);
    let solution = find_solution(&g).unwrap();
    assert_eq!(svg_render(&g, 10, 12, PageSize::A4, true, None), fixture("svg-10x12-abc.svg"));
    assert_eq!(svg_render(&g, 10, 12, PageSize::A4, true, Some(&solution)), fixture("svg-10x12-abc-solved.svg"));

    // maze svg ... -W 9 -H 9 -i xyz -S -L -d 20 -p Letter -s ...
    let g = grid("xyz", 9, 9, 20, true);
    let solution = find_solution(&g).unwrap();
    assert_eq!(svg_render(&g, 9, 9, PageSize::Letter, false, None), fixture("svg-9x9-xyz-straight-loop.svg"));
    assert_eq!(
        svg_render(&g, 9, 9, PageSize::Letter, false, Some(&solution)),
        fixture("svg-9x9-xyz-straight-loop-solved.svg")
    );
}

#[test]
fn pdf_drawing_matches_reportlab() {
    // maze pdf ... -W 5 -H 4 -i abc
    let options = PdfOptions { draw_with_curves: true, page: PageSize::A4, landscape: false, width: 5, height: 4 };
    assert_eq!(pdf_content(&grid("abc", 5, 4, 50, false), &options).0, fixture("pdf-5x4-abc.content"));

    // maze pdf ... -W 8 -H 6 -i xyz -S -L -O L -p A0 -d 10
    let options = PdfOptions { draw_with_curves: false, page: PageSize::A0, landscape: true, width: 8, height: 6 };
    assert_eq!(
        pdf_content(&grid("xyz", 8, 6, 10, true), &options).0,
        fixture("pdf-8x6-xyz-straight-loop-landscape-a0.content")
    );
}

#[test]
fn solves_large_maze_without_overflowing_the_stack() {
    let g = grid("big", 168, 240, 50, false);
    let solution = find_solution(&g).unwrap();
    assert_eq!(solution.first(), Some(&(0, 0)));
    assert_eq!(solution.last(), Some(&(167, 239)));
}
